self.onInit = function () {
    var NULL_UUID = '13814000-1dd2-11b2-8080-808080808080';

    var root = self.ctx.$container[0];
    var $ = function (s) { return root.querySelector(s); };
    var http = self.ctx.http;
    var devSel = $('.as-device');
    var custSel = $('.as-customer');
    var nameBox = $('.as-name');
    var btn = $('.as-save');
    var msg = $('.as-msg');
    var devices = [];
    var customers = [];

    function show(text, ok) {
        msg.textContent = text;
        msg.className = 'dv-msg as-msg ' + (ok ? 'dv-ok' : 'dv-err');
    }

    function errText(e) {
        if (!e) { return 'Ismeretlen hiba'; }
        var m = (e.error && e.error.message) ? e.error.message : '';
        return (e.status ? e.status + ' ' : '') + (e.url ? '[' + e.url + '] ' : '') + (m || 'Ismeretlen hiba');
    }

    function getAll(url, cb) {
        var items = [];
        (function next(page) {
            http.get(url + (url.indexOf('?') >= 0 ? '&' : '?') + 'pageSize=100&page=' + page).subscribe(
                function (res) {
                    items = items.concat(res.data || []);
                    if (res.hasNext) { next(page + 1); } else { cb(null, items); }
                },
                function (e) { cb(errText(e)); }
            );
        })(0);
    }

    function fillSelect(sel, placeholder, items, textOf) {
        sel.textContent = '';
        var o0 = document.createElement('option');
        o0.value = '';
        o0.textContent = placeholder;
        sel.appendChild(o0);
        items.forEach(function (it) {
            var o = document.createElement('option');
            o.value = it.id.id;
            o.textContent = textOf(it);
            sel.appendChild(o);
        });
    }

    function selectedDevice() { return devices[devSel.selectedIndex - 1]; }
    function selectedCustomer() { return customers[custSel.selectedIndex - 1]; }

    // machineCount attribute of the customer (0 = unknown, no limit)
    function getMachineCount(cid, cb) {
        http.get('/api/plugins/telemetry/CUSTOMER/' + cid + '/values/attributes/SERVER_SCOPE?keys=machineCount').subscribe(
            function (arr) {
                var item = (arr || []).filter(function (a) { return a.key === 'machineCount'; })[0];
                cb(item ? (parseInt(item.value, 10) || 0) : 0);
            },
            function () { cb(0); }
        );
    }

    // lowest free number: "<customer> #N"
    function nextName(customer, cb) {
        getAll('/api/customer/' + customer.id.id + '/devices?sortProperty=name&sortOrder=ASC', function (err, devs) {
            if (err) { cb(err); return; }
            var esc = customer.title.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            var re = new RegExp('^' + esc + ' #(\\d+)$');
            var used = {};
            devs.forEach(function (d) {
                var m = re.exec(d.name);
                if (m) { used[parseInt(m[1], 10)] = true; }
            });
            var n = 1;
            while (used[n]) { n++; }
            getMachineCount(customer.id.id, function (limit) {
                if (limit && n > limit) {
                    cb('minden gép hozzá van adva (' + limit + '/' + limit + ')');
                    return;
                }
                cb(null, customer.title + ' #' + n);
            });
        });
    }

    function updateName() {
        var c = selectedCustomer();
        msg.textContent = '';
        if (!c) { nameBox.value = ''; return; }
        nameBox.value = '...';
        nextName(c, function (err, name) {
            if (err) { nameBox.value = ''; show('Hiba: ' + err, false); }
            else { nameBox.value = name; }
        });
    }

    function loadLists() {
        // devices that belong to no customer
        getAll('/api/tenant/devices?sortProperty=name&sortOrder=ASC', function (err, list) {
            if (err) { show('A gépek betöltése nem sikerült: ' + err, false); return; }
            devices = list.filter(function (d) {
                return !d.customerId || !d.customerId.id || d.customerId.id === NULL_UUID;
            });
            fillSelect(devSel, devices.length ? 'Válassz gépet...' : 'Nincs hozzárendelhető gép', devices, function (d) {
                return d.name + (d.label && d.label !== d.name ? ' (' + d.label + ')' : '');
            });
        });
        getAll('/api/customers?sortProperty=title&sortOrder=ASC', function (err, list) {
            if (err) { show('Az ügyfelek betöltése nem sikerült: ' + err, false); return; }
            customers = list;
            fillSelect(custSel, 'Válassz ügyfelet...', customers, function (c) { return c.title; });
        });
    }

    custSel.addEventListener('change', updateName);

    btn.addEventListener('click', function () {
        var dev = selectedDevice();
        var c = selectedCustomer();
        if (!dev) { show('Válassz gépet.', false); return; }
        if (!c) { show('Válassz ügyfelet.', false); return; }

        btn.disabled = true;
        show('Hozzárendelés...', true);

        nextName(c, function (err, newName) {
            if (err) { show('Hiba: ' + err, false); btn.disabled = false; return; }
            var did = dev.id.id;
            var oldName = dev.name;

            // 1) owner: the customer
            http.post('/api/owner/CUSTOMER/' + c.id.id + '/DEVICE/' + did, []).subscribe(
                function () { rename(); },
                function (e) {
                    if (e && e.status === 200) { rename(); return; }     // empty answer is not an error
                    show('Tulajdonos hiba: ' + errText(e), false);
                    btn.disabled = false;
                }
            );

            // 2) new name; the old name (MAC suffix) stays as the label
            function rename() {
                http.get('/api/device/' + did).subscribe(
                    function (d) {
                        d.label = d.label || oldName;
                        d.name = newName;
                        http.post('/api/device', d).subscribe(
                            function () {
                                show('Kész: ' + oldName + ' → ' + newName + ' (hozzárendelve).', true);
                                btn.disabled = false;
                                nameBox.value = '';
                                loadLists();
                            },
                            function (e) {
                                show('A gép hozzá van rendelve, de az átnevezés nem sikerült: ' + errText(e), false);
                                btn.disabled = false;
                                loadLists();
                            }
                        );
                    },
                    function (e) {
                        show('A gép hozzá van rendelve, de nem olvasható: ' + errText(e), false);
                        btn.disabled = false;
                        loadLists();
                    }
                );
            }
        });
    });

    loadLists();
};

self.onDestroy = function () {};

